using System;
using System.Linq;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;

namespace Ara {
 public static class SleepTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();GridEngine.Ensure(s,s.GetDay(DateTime.Today));return s;}
  public static void Run(Action<string,Action> check,string dir){
   check("sleep: lighting spans exactly two hours in both lanes without creating records",()=>{var s=New();var d=s.Days[0];var p=GridEngine.Build(s,d);DateTime sleep=Adaptive.EstimatedSleep(s,d,p);using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();b.SetData(d.Wake.Date,p.Blocks,d.Records);b.EstimatedSleep=sleep;b.Jump(sleep.AddHours(-2));int begin=b.Index(sleep)-12;Assert(!b.IsLightsOut(begin-1)&&b.IsLightsOut(begin)&&b.IsLightsOut(begin+11)&&!b.IsLightsOut(begin+12),"half-open twelve cells");using(var bitmap=new Bitmap(b.Width,b.Height)){b.DrawToBitmap(bitmap,new Rectangle(Point.Empty,b.Size));for(int lane=0;lane<2;lane++){var r=b.CellRect(lane,begin);Color color=lane==0?Color.White:Color.FromArgb(242,244,240);Assert(bitmap.GetPixel(r.X+2,r.Y+2)==Timetable.LightsColor(color),"both lane tint");}bitmap.Save(Path.Combine(dir,"lights-out-smoke.png"));}Assert(d.GridBase.Count==14&&d.Records.Count==0,"no data changes");f.Close();}});
   check("sleep: forecast and normal bedtime are one hour after yogurt start",()=>{var s=New();var d=s.Days[0];var p=GridEngine.Build(s,d);var yogurt=p.Blocks.Single(x=>x.MealId=="b16");Assert(Adaptive.EstimatedSleep(s,d,p)==yogurt.Start.AddHours(1)&&Adaptive.Target(s,d)==yogurt.Start.AddHours(1),"start plus 60, not end plus 60");Assert(p.Overflow==0&&d.GridBase.Count==14&&d.Records.Count==0,"marker does not occupy scheduling budget or actual data");});
   check("sleep: late actual yogurt keeps bedtime fixed and reports constraint debt",()=>{var s=New();var d=s.Days[0];var p=GridEngine.Build(s,d);var yogurt=p.Blocks.Single(x=>x.MealId=="b16");d.Records.Add(new CellBlock{Id="actual-yogurt",MealId="b16",Category="식사",Name="5끼니",Start=yogurt.Start.AddMinutes(90),Count=3,Score=2});p=GridEngine.Build(s,d);Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End&&p.Overflow==60,"actual sleep forecast and unchanged original goal");d.Records[0].Start=d.Records[0].Start.AddMinutes(-30);p=GridEngine.Build(s,d);Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End&&p.Overflow==30&&GridEngine.Total(d)==6,"recomputes without changing score");});
   check("sleep: omitted yogurt respects the fourth-meal rest floor while keeping the original target",()=>{var s=New();var d=s.Days[0];d.Records.Add(new CellBlock{Id="late-fourth",MealId="b15",Category="식사",Name="4끼니",Start=d.Wake.AddMinutes(930),Count=3});var p=GridEngine.Build(s,d);Assert(!p.Blocks.Any(x=>x.MealId=="b16")&&Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End.AddHours(2)&&p.Overflow==90,"rest floor reports conflict without moving bedtime");});
   check("sleep: timeline paints exactly one planned ten-minute cell",()=>{var s=New();var d=s.Days[0];var p=GridEngine.Build(s,d);DateTime sleep=Adaptive.EstimatedSleep(s,d,p);using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();b.SetData(d.Wake.Date,p.Blocks,d.Records);b.EstimatedSleep=sleep;b.Jump(sleep.AddHours(-1));using(var bitmap=new Bitmap(b.Width,b.Height)){b.DrawToBitmap(bitmap,new Rectangle(Point.Empty,b.Size));int index=b.Index(sleep),hour=index/6;int count=0;Color purple=Color.FromArgb(214,209,240);for(int column=0;column<6;column++){var planned=b.CellRect(0,hour*6+column);var actual=b.CellRect(1,hour*6+column);if(bitmap.GetPixel(planned.X+2,planned.Y+2)==purple)count++;Assert(bitmap.GetPixel(actual.X+2,actual.Y+2)!=purple,"actual row unmarked");}Assert(count==1,"one ten-minute cell only");bitmap.Save(Path.Combine(dir,"sleep-marker-smoke.png"));}f.Close();}});
  }
 }
}
